create or replace function public.save_workout(payload jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$declare w public.workout_sessions;item jsonb;s jsonb;kind text;begin if auth.uid() is null then raise exception 'Authentication required';end if;if payload->>'mutation_id' is null or payload->>'revision' is null or (payload->>'revision')::integer<0 then raise exception 'Mutation ID and revision required';end if;if jsonb_typeof(payload->'workout_exercises') is distinct from 'array' then raise exception 'Exercises must be a list';end if;if jsonb_array_length(payload->'workout_exercises')>50 then raise exception 'Too many exercises';end if;insert into public.workout_sessions(id,user_id,workout_date,title,started_at) values((payload->>'id')::uuid,auth.uid(),(payload->>'workout_date')::date,payload->>'title',(payload->>'started_at')::timestamptz) on conflict(id) do nothing;select * into w from public.workout_sessions where id=(payload->>'id')::uuid for update;if w.id is null then raise exception 'Workout unavailable';end if;if w.last_mutation_id=(payload->>'mutation_id')::uuid then return jsonb_build_object('revision',w.revision);end if;if w.revision<>(payload->>'revision')::integer then raise exception 'VERSION_CONFLICT';end if;if payload->>'completed_at' is not null and not exists(select 1 from jsonb_array_elements(payload->'workout_exercises') e cross join lateral jsonb_array_elements(e->'exercise_sets') candidate where candidate->>'completed_at' is not null) then raise exception 'Log at least one set before completing a workout';end if;for item in select value from jsonb_array_elements(payload->'workout_exercises') loop if jsonb_typeof(item->'exercise_sets') is distinct from 'array' then raise exception 'Sets must be a list';end if;if jsonb_array_length(item->'exercise_sets')>100 then raise exception 'Too many sets';end if;if not exists(select 1 from public.exercises e where e.id=(item->>'exercise_id')::uuid and(e.archived_at is null or exists(select 1 from public.workout_exercises we where we.session_id=w.id and we.exercise_id=e.id))) then raise exception 'Exercise unavailable';end if;end loop;delete from public.workout_exercises where session_id=w.id;for item in select value from jsonb_array_elements(payload->'workout_exercises') loop insert into public.workout_exercises(id,session_id,exercise_id,position,notes,rest_seconds) values((item->>'id')::uuid,w.id,(item->>'exercise_id')::uuid,(item->>'position')::integer,coalesce(item->>'notes',''),coalesce((item->>'rest_seconds')::integer,90));for s in select value from jsonb_array_elements(item->'exercise_sets') loop insert into public.exercise_sets(id,workout_exercise_id,set_number,set_type,weight_kg,input_unit,reps,completed_at) values((s->>'id')::uuid,(item->>'id')::uuid,(s->>'set_number')::integer,s->>'set_type',(s->>'weight_kg')::numeric,s->>'input_unit',(s->>'reps')::integer,(s->>'completed_at')::timestamptz);end loop;end loop;update public.workout_sessions set workout_date=(payload->>'workout_date')::date,title=payload->>'title',notes=coalesce(payload->>'notes',''),started_at=(payload->>'started_at')::timestamptz,completed_at=(payload->>'completed_at')::timestamptz,revision=revision+1,last_mutation_id=(payload->>'mutation_id')::uuid where id=w.id returning * into w;return jsonb_build_object('revision',w.revision);end$$;create or replace function public.save_template(payload jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$declare t public.workout_templates;item jsonb;begin if auth.uid() is null then raise exception 'Authentication required';end if;if payload->>'mutation_id' is null or payload->>'revision' is null or (payload->>'revision')::integer<0 then raise exception 'Mutation ID and revision required';end if;if jsonb_typeof(payload->'template_exercises') is distinct from 'array' then raise exception 'Choose between 1 and 50 exercises';end if;if jsonb_array_length(payload->'template_exercises') not between 1 and 50 then raise exception 'Choose between 1 and 50 exercises';end if;insert into public.workout_templates(id,user_id,name) values((payload->>'id')::uuid,auth.uid(),payload->>'name') on conflict(id) do nothing;select * into t from public.workout_templates where id=(payload->>'id')::uuid and archived_at is null for update;if t.id is null then raise exception 'Routine unavailable';end if;if t.last_mutation_id=(payload->>'mutation_id')::uuid then return jsonb_build_object('revision',t.revision);end if;if t.revision<>(payload->>'revision')::integer then raise exception 'VERSION_CONFLICT';end if;for item in select value from jsonb_array_elements(payload->'template_exercises') loop if not exists(select 1 from public.exercises e where e.id=(item->>'exercise_id')::uuid and(e.archived_at is null or exists(select 1 from public.template_exercises te where te.template_id=t.id and te.exercise_id=e.id))) then raise exception 'Exercise unavailable';end if;if item->>'target_reps_max' is not null and (item->>'target_reps_max')::integer<(item->>'target_reps')::integer then raise exception 'The top of a rep range cannot be below the bottom';end if;end loop;delete from public.template_exercises where template_id=t.id;for item in select value from jsonb_array_elements(payload->'template_exercises') loop insert into public.template_exercises(id,template_id,exercise_id,position,target_sets,target_reps,target_reps_max,rest_seconds) values((item->>'id')::uuid,t.id,(item->>'exercise_id')::uuid,(item->>'position')::integer,(item->>'target_sets')::integer,(item->>'target_reps')::integer,(item->>'target_reps_max')::integer,(item->>'rest_seconds')::integer);end loop;update public.workout_templates set name=payload->>'name',revision=revision+1,last_mutation_id=(payload->>'mutation_id')::uuid where id=t.id returning * into t;return jsonb_build_object('revision',t.revision);end$$;
